#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum EFMPlusState {
    State1 = 0, State2 = 1, State3 = 2, State4 = 3
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EFMPlusStateMachine {
    state: EFMPlusState
}

impl Default for EFMPlusStateMachine {
    fn default() -> Self {
        Self::new()
    }
}

impl EFMPlusStateMachine {
    #[inline]
    pub fn new() -> Self {
        Self { state: EFMPlusState::State1 }
    }
    #[inline]
    pub fn reset(&mut self) { self.state = EFMPlusState::State1; }
    #[inline]
    pub fn next(&mut self, byte: u8) {
        self.state = EFM_TRANSITIONS[self.state as usize][byte as usize];
    }
    #[inline]
    pub fn state(self) -> EFMPlusState {
        self.state
    }
    #[inline]
    pub fn choose(&mut self, density: TransitionDensity) -> u8 {
        let byte = TRANSITION_STRATEGY
            [self.state as usize]
            [density as usize];
        self.next(byte);
        byte
    }
}

const TRANSITION_STRATEGY: [[u8; 2]; 4] = [
    [0x5F, 0x62], // State 1
    // 0000001000000010 ; 0010010010010010
    [0x40, 0x62], // State 2
    // 0000010000000010 ; 0010010010010010
    [0xB2, 0x70], // State 3
    // 1000000100000010 ; 1001001001001001
    [0xB2, 0x70], // State 4
    // 1000000100000010 ; 1001001001001001
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum TransitionDensity {
    LowDensity = 0,
    HighDensity = 1,
}